code.Java:
class Solution {
    public long reverseBits(long n) {
        n &= 0xFFFFFFFFL;
        long result = 0;
        for (int i = 0; i < 32; i++) {
            result = (result << 1) | (n & 1L);
            n >>>= 1;
        }
        return result;
    }
}

